function norm(s){return String(s??'').normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();}
function hav(a,b){const R=6371e3,toRad=x=>x*Math.PI/180,dLat=toRad(b.lat-a.lat),dLon=toRad(b.lon-a.lon);const x=Math.sin(dLat/2)**2+Math.cos(toRad(a.lat))*Math.cos(toRad(b.lat))*Math.sin(dLon/2)**2;return 2*R*Math.asin(Math.sqrt(x));}
export function resolveSpatialIdentity(query,candidates,{acceptScore=.82,ambiguousDelta=.05,maxDistanceM=1500}={}){
  if(query?.externalMasterId) {const exact=candidates.find(c=>(c.externalIds??[]).includes(query.externalMasterId)); if(exact)return Object.freeze({state:'MATCHED_EXACT_EXTERNAL_ID',candidate:structuredClone(exact),score:1});}
  const qn=norm(query?.name),qa=norm(query?.address); const scored=candidates.map(c=>{const cn=norm(c.name),ca=norm(c.address);let score=0;if(qn&&cn)score+=qn===cn?.55:(cn.includes(qn)||qn.includes(cn)?.35:0);if(qa&&ca)score+=qa===ca?.2:(ca.includes(qa)||qa.includes(ca)?.1:0);if(query?.lat!=null&&query?.lon!=null&&c.lat!=null&&c.lon!=null){const d=hav(query,c);score+=Math.max(0,.25*(1-d/maxDistanceM));return {candidate:c,score,distanceM:d};}return {candidate:c,score,distanceM:null};}).sort((a,b)=>b.score-a.score);
  const top=scored[0],second=scored[1]; if(!top||top.score<acceptScore)return Object.freeze({state:'UNMATCHED',candidates:Object.freeze(scored.slice(0,3))}); if(second&&top.score-second.score<ambiguousDelta)return Object.freeze({state:'AMBIGUOUS',candidates:Object.freeze(scored.slice(0,3))}); return Object.freeze({state:'MATCHED',candidate:structuredClone(top.candidate),score:top.score,distanceM:top.distanceM});
}
